void show_stack ( struct task_struct * task , unsigned long * esp ) { unsigned long addr , * stack ; int i ; if ( esp == NULL ) { esp = ( unsigned long * ) & esp ; } stack = esp ; printk ( "Stack dump [0x%08lx]:\n" , ( unsigned long ) esp ) ; for ( i = 0 ; i < kstack_depth_to_print ; i ++ ) { if ( kstack_end ( stack ) ) { break ; } if ( __get_user ( addr , stack ) ) { printk ( "Failing address 0x%lx\n" , ( unsigned long ) stack ) ; break ; } stack ++ ; printk ( "sp + %02d: 0x%08lx\n" , i * 4 , addr ) ; } printk ( "\n" ) ; return ; } 